#!/bin/sh

set -e
cat << @
/* AUTOGENERATED by a_embedfilesdir.sh - do not edit */

#include <stddef.h>
#define _ZEROPAD "\0\0\0\0\0"
struct EmbedFile {
   const char *name;
   const char *s;
   size_t len;
} embedfilesdir[] = {
@

H () {
   echo '{"'"$1"'",'
   awk '{ print "\""$0"\\n\""; n+=length+1 }
        END { print "_ZEROPAD, "n"}," }'
}

H stddef.h << @
#pragma once
