H limits.h << @
#pragma once
/* Tell glibc not to try to recursively #include_next gcc's <limits.h> */
#if defined __GNUC__ && !defined _GCC_LIMITS_H
#define _GCC_LIMITS_H_
#endif
/* We want the system libc header for POSIX constants */
#ifdef __STDC_HOSTED__
#include_next <limits.h>
#endif

