@

cat << @
   {NULL}
};

#ifdef EMBEDFILESDIR_CHECKSIZES
#include <string.h>
#include <stdio.h>
int main() {
   int rc = 0;
   for (int i = 0; embedfilesdir[i].name; ++i) {
      struct EmbedFile *e = &embedfilesdir[i];
      if (strlen(e->s) != e->len) {
         fprintf(stderr, "%s expected %d actual %d\n",
                  e->name, (int)e->len, (int)strlen(e->s));
         ++rc;
      }
   }
   return rc;
}
#endif
@

